export class RecursiveAdversarialTesting {
  constructor(agents) {
    this.agents = agents;
  }

  simulateAdversarialCycle() {
    this.agents.forEach(agent => {
      const adversarialResults = this.agents.map(opponent => {
        if (agent !== opponent) {
          return this.testInteraction(agent, opponent);
        }
      });
      agent.update(adversarialResults);
    });
  }

  testInteraction(agent, opponent) {
    const vulnerabilities = agent.detectWeakness(opponent);
    return { agent, opponent, vulnerabilities };
  }
}